//! The native terrain look model against the web client's: every built-in
//! look, applied, stacked with fitted ranges and turned into uniforms, must
//! match `lidar-render.js` + `gpu-terrain-shaders.js` (cases generated by
//! native/shaders/extract.cjs).

use std::collections::BTreeMap;

use csk_app::render::{Appearance, Lighting, Look, Spectrum};
use csk_app::terrain::{Fit, Stack, Studio, catalog};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Input {
    style: String,
    opacity: f64,
    look: Look,
    lighting: Lighting,
    spectrum: Spectrum,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    look: String,
    fitted: BTreeMap<String, Fit>,
    rem_flat_base: f64,
    input: Input,
    stack: Option<Stack>,
    values: BTreeMap<String, serde_json::Value>,
}

/// Uniforms the scene sets per frame from the camera.
const CAMERA: [&str; 6] = ["u_centerMerc", "u_zoom", "u_bearingRad", "u_cssSize", "u_dpr", "u_waterMask"];

#[test]
fn looks_compile_to_the_web_stacks_and_uniforms() {
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("../../../shaders/generated/terrain-cases.json")).expect("cases");
    assert_eq!(cases.len(), catalog().looks.len());
    for case in cases {
        let look = catalog().look(&case.look).expect("look");
        let mut studio = Studio::default();
        let style = studio.apply_scene(&look.scene, Some(&look.id));
        assert_eq!(style, case.input.style, "{}", case.look);
        let stack = studio.build_stack(&style, &case.fitted, case.rem_flat_base, None);
        assert_eq!(stack, case.stack, "{} stack", case.look);
        let appearance = Appearance {
            style,
            opacity: case.input.opacity,
            look: case.input.look,
            lighting: case.input.lighting,
            spectrum: case.input.spectrum,
            spectrum_opacity: 1.0,
            stack,
        };
        let native: BTreeMap<&str, Vec<f32>> = appearance.uniforms().into_iter().collect();
        for (name, expected) in &case.values {
            if CAMERA.contains(&name.as_str()) {
                continue;
            }
            let expected: Vec<f64> = match expected {
                serde_json::Value::Array(v) => v.iter().map(|x| x.as_f64().expect("number")).collect(),
                v => vec![v.as_f64().expect("number")],
            };
            let got = native.get(name.as_str()).unwrap_or_else(|| panic!("{}: no native {name}", case.look));
            assert_eq!(got.len(), expected.len(), "{} {name} length", case.look);
            for (g, e) in got.iter().zip(&expected) {
                assert!(
                    (f64::from(*g) - e).abs() <= 1e-6 * e.abs().max(1.0),
                    "{} {name}: {got:?} vs {expected:?}",
                    case.look
                );
            }
        }
        let mut uniforms = csk_gpu::Uniforms::default();
        appearance.apply(&mut uniforms).expect("every appearance uniform is in the shading layout");
    }
}
